def close_all(self, close_client: Callable[[Any], Any]) -> None:
    """Close and clear all cached clients on a best-effort basis.

    Async clients (e.g. an ``aiohttp.ClientSession`` held inside an OpenAI
    or Volcengine SDK client) bind their transports to the event loop that
    first used them. Closing such a client from a *different* loop raises
    ``RuntimeError: ... attached to a different loop`` and leaves the
    exception unretrieved. To avoid that, every client is closed on the
    loop it was created in:

    * loop-bound clients are dispatched to their own loop when it is still
      running, and skipped (best-effort) once that loop has closed;
    * unbound (fallback) clients are closed on the current loop, or on a
      freshly created one when no loop is running.
    """
    with self._lock:
        clients = list(self._clients_by_loop.values())
        self._clients_by_loop.clear()
        if self._fallback_client is not None:
            clients.append(self._fallback_client)
            self._fallback_client = None
        loop_by_client = dict(self._loop_by_client)
        self._loop_by_client.clear()

    if not clients:
        return

    try:
        current_loop = asyncio.get_running_loop()
    except RuntimeError:
        current_loop = None

    bound_clients: list[tuple[Any, asyncio.AbstractEventLoop]] = []
    unbound_clients: list[Any] = []
    for client in clients:
        client_loop = loop_by_client.get(client)
        if client_loop is None:
            unbound_clients.append(client)
        else:
            bound_clients.append((client, client_loop))

    # Unbound clients have no loop affinity and are safe to close on any loop.
    if unbound_clients:
        if current_loop is not None and current_loop.is_running():
            current_loop.create_task(
                self._close_clients(unbound_clients, close_client)
            )
        else:
            try:
                asyncio.run(self._close_clients(unbound_clients, close_client))
            except RuntimeError:
                for client in unbound_clients:
                    self._try_close_direct(client, close_client)

    # Loop-bound clients must be closed on their originating loop.
    for client, client_loop in bound_clients:
        if client_loop.is_closed():
            # Originating loop is gone; its transports are already torn down.
            continue
        if client_loop.is_running():
            try:
                asyncio.run_coroutine_threadsafe(
                    self._close_clients([client], close_client), client_loop
                )
            except RuntimeError:
                self._try_close_direct(client, close_client)
        else:
            try:
                client_loop.run_until_complete(
                    self._close_clients([client], close_client)
                )
            except RuntimeError:
                self._try_close_direct(client, close_client)

@staticmethod
def _try_close_direct(client: Any, close_client: Callable[[Any], Any]) -> None:
    """Best-effort synchronous close used only when no usable loop exists.

    The client's transports are bound to a loop we can no longer drive, so a
    clean (awaited) close is impossible. Swallow errors on purpose, and
    discard any awaitable returned by ``close_client`` to avoid the
    "coroutine was never awaited" warning.
    """
    try:
        result = close_client(client)
        if inspect.isawaitable(result):
            try:
                result.close()
            except Exception:
                pass
    except Exception:
        pass

