# Loop-bound clients must be closed on their originating loop.
for client, client_loop in bound_clients:
    if client_loop.is_closed():
        # Originating loop is gone; its transports are already torn down.
        continue
    if current_loop is not None and current_loop is client_loop:
        # Same running loop: schedule the close; it runs on the live loop.
        current_loop.create_task(
            self._close_clients([client], close_client)
        )
    elif client_loop.is_running():
        # Other thread's running loop: schedule and wait for completion
        # (blocking here is safe - we are not in that loop's thread, so
        # there is no deadlock, and waiting guarantees a clean close).
        try:
            fut = asyncio.run_coroutine_threadsafe(
                self._close_clients([client], close_client), client_loop
            )
            fut.result(timeout=30)
        except Exception:
            self._try_close_direct(client, close_client)
    else:
        # Idle/non-running loop we cannot drive: best-effort skip.
        self._try_close_direct(client, close_client)
